SENSITIVE = {"password", "token", "api_key", "authorization", "secret"}

def redact_fields(fields):
    out = {}
    for k, v in fields.items():
        out[k] = REDACTED if k.lower() in SENSITIVE else v
    return out

from orgops.logging.context import get_request_id

def build_payload(event, level, **fields):
    payload = {"event": event, "level": level}
    payload.update(fields)
    rid = get_request_id()
    if rid is not None:
        payload["request_id"] = rid
    return payload

